WITH base AS (SELECT id, email, country, city, segment, signup_date, is_active, credit_limit, age, CAST(age AS STRING) age_num FROM customers WHERE segment IS NOT NULL AND city IS DISTINCT FROM 'Chiang Mai') SELECT id, country, city, signup_date, is_active, COUNT(age) OVER w_hist running_count_age, MAX(age) OVER w_hist running_max_age, AVG(age) OVER w_hist running_avg_age FROM base WHERE city != 'Singapore' WINDOW w_hist AS (PARTITION BY segment ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
